int minEatingSpeed(std::vector<int>& piles, int h) {
    auto canFinish = [&](int speed) {
        long long hours = 0;
        for (int p : piles) hours += (p + speed - 1) / speed;
        return hours <= h;
    };
    int low = 1, high = *std::max_element(piles.begin(), piles.end()), ans = high;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (canFinish(mid)) {
            ans = mid;
            high = mid - 1;
        } else low = mid + 1;
    }
    return ans;
}

