def splitArray(nums: list[int], k: int) -> int:
    def can_split(max_sum):
        count = 1
        curr_sum = 0
        for num in nums:
            if curr_sum + num > max_sum:
                count += 1
                curr_sum = num
            else:
                curr_sum += num
        return count <= k

    low, high = max(nums), sum(nums)
    ans = high
    while low <= high:
        mid = (low + high) // 2
        if can_split(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

