                count++;
                currSum = num;
            } else currSum += num;
        }
        return count <= k;
    };
    let low = Math.max(...nums);
    let high = nums.reduce((a, b) => a + b, 0), ans = high;
    while (low <= high) {
        let mid = Math.floor((low + high) / 2);
        if (canSplit(mid)) {
            ans = mid;
            high = mid - 1;
        } else low = mid + 1;
    }
    return ans;
}

