        int[] c2 = new int[26];
        for (int i = 0; i < s1.length(); i++) {
            c1[s1.charAt(i) - 'a']++;
            c2[s2.charAt(i) - 'a']++;
        }
        if (Arrays.equals(c1, c2)) return true;
        for (int i = 0; i < s1.length(); i++) {
            c2[s2.charAt(i) - 'a']++;
            c2[s2.charAt(i - s1.length()) - 'a']--;
            if (Arrays.equals(c1, c2)) return true;
        }
        return false;
    }
}

function checkInclusion(s1, s2) {
  if (s1.length > s2.length) return false;
  const c1 = new Array(26).fill(0);
  const c2 = new Array(26).fill(0);
  const codeA = 'a'.charCodeAt(0);
  for (let i = 0; i < s1.length; i++) {
    c1[s1.charCodeAt(i) - codeA]++;
    c2[s2.charCodeAt(i) - codeA]++;
  }
  if (c1.every((val, idx) => val === c2[idx])) return true;
  for (let i = s1.length; i < s2.length; i++) {
    c2[s2.charCodeAt(i) - codeA]++;
    c2[s2.charCodeAt(i - s1.length()) - codeA]--;
    if (c1.every((val, idx) => val === c2[idx])) return true;
  }
  return false;
}

