class MinHeap:
    def __init__(self):
        self.heap = []
    def push(self, val):
        self.heap.append(val)
        self._shift_up(len(self.heap) - 1)
    def pop(self):
        if not self.heap: return None
        if len(self.heap) == 1: return self.heap.pop()
        min_val = self.heap[0]
        self.heap[0] = self.heap.pop()
        self._shift_down(0)
        return min_val
    def _shift_up(self, i):
        parent = (i - 1) // 2
        if i > 0 and self.heap[i] < self.heap[parent]:
            self.heap[i], self.heap[parent] = self.heap[parent], self.heap[i]
            self._shift_up(parent)
    def _shift_down(self, i):
        left, right, smallest = 2*i + 1, 2*i + 2, i
        if left < len(self.heap) and self.heap[left] < self.heap[smallest]: smallest = left
        if right < len(self.heap) and self.heap[right] < self.heap[smallest]: smallest = right
        if smallest != i:
            self.heap[i], self.heap[smallest] = self.heap[smallest], self.heap[i]
            self._shift_down(smallest)

