        this.capacity = capacity;
        this.q = [];
        this.enqueueWaiters = [];
        this.dequeueWaiters = [];
    }
    async enqueue(element) {
        while (this.q.length === this.capacity) {
            await new Promise(resolve => this.enqueueWaiters.push(resolve));
        }
        this.q.push(element);
        if (this.dequeueWaiters.length > 0) {
            const resolve = this.dequeueWaiters.shift();
            resolve();
        }
    }
    async dequeue() {
        while (this.q.length === 0) {
            await new Promise(resolve => this.dequeueWaiters.push(resolve));
        }
        const val = this.q.shift();
        if (this.enqueueWaiters.length > 0) {
            const resolve = this.enqueueWaiters.shift();
            resolve();
        }
        return val;
    }
    size() { return this.q.length; }
}

def infix_to_postfix(s: str) -> str:
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    stack = []
    res = []
    for ch in s:
        if ch.isalnum():
            res.append(ch)
        elif ch == '(':
            stack.append(ch)
        elif ch == ')':
            while stack and stack[-1] != '(':
                res.append(stack.pop())
            stack.pop()
        else:
            while stack and precedence.get(stack[-1], 0) >= precedence.get(ch, 0):
                res.append(stack.pop())
            stack.append(ch)
    while stack:
        res.append(stack.pop())
    return ''.join(res)

