def infix_to_prefix(s: str) -> str:
    # Step 1: Reverse string and swap '(' with ')'
    rev = []
    for ch in reversed(s):
        if ch == '(': rev.append(')')
        elif ch == ')': rev.append('(')
        else: rev.append(ch)
    s_rev = ''.join(rev)

    # Step 2: Get postfix
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    stack, res = [], []
    for ch in s_rev:
        if ch.isalnum(): res.append(ch)
        elif ch == '(': stack.append(ch)
        elif ch == ')':
            while stack and stack[-1] != '(':
                res.append(stack.pop())
            stack.pop()
        else:
            while stack and precedence.get(stack[-1], 0) > precedence.get(ch, 0):
                res.append(stack.pop())
            stack.append(ch)
    while stack: res.append(stack.pop())

    # Step 3: Reverse result
    return ''.join(reversed(res))

