def removeInvalidParentheses(s: str) -> list[str]:
    def is_valid(string):
        count = 0
        for c in string:
            if c == '(': count += 1
            elif c == ')':
                count -= 1
                if count < 0: return False
        return count == 0

    visited = {s}
    q = deque([s])
    res = []
    found = False

