        curr = q.popleft()
        if is_valid(curr):
            res.append(curr)
            found = True
        if found: continue
        for i in range(len(curr)):
            if curr[i] not in '()': continue
            nxt = curr[:i] + curr[i+1:]
            if nxt not in visited:
                visited.add(nxt)
                q.append(nxt)
    return res

