    }
    vector<vector<int>> res;
    for (auto& [col, rows] : nodes) {
        vector<int> colVals;
        for (auto& [row, vals] : rows) {
            colVals.insert(colVals.end(), vals.begin(), vals.end());
        }
        res.push_back(colVals);
    }
    return res;
}

