        prefix.put(currSum, prefix.getOrDefault(currSum, 0) + 1);
        count += dfs(node.left, currSum, targetSum, prefix) + dfs(node.right, currSum, targetSum, prefix);
        prefix.put(currSum, prefix.get(currSum) - 1); // Backtrack
