class Codec:
    def serialize(self, root) -> str:
        res = []
        def dfs(node):
            if not node:
                res.append('null')
                return
            res.append(str(node.val))
            dfs(node.left)
            dfs(node.right)
        dfs(root)
        return ','.join(res)

    def deserialize(self, data: str):
        vals = iter(data.split(','))
        def dfs():
            val = next(vals)
            if val == 'null':
                return None
            node = {'val': int(val), 'left': None, 'right': None}
            node['left'] = dfs()
            node['right'] = dfs()
            return node
        return dfs()

