class BSTIterator:
    def __init__(self, root):
        self.stack = []
        self._push_all(root)

    def _push_all(self, node):
        while node:
            self.stack.append(node)
            node = node.left

    def next(self) -> int:
        node = self.stack.pop()
        self._push_all(node.right)
        return node.val

    def hasNext(self) -> bool:
        return len(self.stack) > 0

