public class Solution {
    static class TreeNode { int val; TreeNode left, right; }
    public boolean findTarget(TreeNode root, int k) {
        Deque<TreeNode> stL = new ArrayDeque<>(), stR = new ArrayDeque<>();
        pushL(root, stL); pushR(root, stR);
        while (!stL.isEmpty() && !stR.isEmpty() && stL.peek() != stR.peek()) {
            int sum = stL.peek().val + stR.peek().val;
            if (sum == k) return true;
            if (sum < k) {
                TreeNode n = stL.pop();
                pushL(n.right, stL);
            } else {
                TreeNode n = stR.pop();
                pushR(n.left, stR);
            }
        }
        return false;
    }
    private void pushL(TreeNode n, Deque<TreeNode> st) { while (n != null) { st.push(n); n = n.left; } }
    private void pushR(TreeNode n, Deque<TreeNode> st) { while (n != null) { st.push(n); n = n.right; } }
}

