def is_bipartite(graph):
    n = len(graph)
    color = [-1] * n
    for i in range(n):
        if color[i] != -1: continue
        queue = deque([i])
        color[i] = 0
        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    queue.append(v)
                elif color[v] == color[u]:
                    return False
    return True

