public class PrimsMST {
    public int spanningTree(int V, List<List<int[]>> adj) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        boolean[] visited = new boolean[V];
        pq.add(new int[]{0, 0});
        int sum = 0;

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int wt = curr[0], u = curr[1];
            if (visited[u]) continue;
            visited[u] = true;
            sum += wt;
            for (int[] nbr : adj.get(u)) {
                if (!visited[nbr[0]]) {
                    pq.add(new int[]{nbr[1], nbr[0]});
                }
            }
        }
        return sum;
    }
}

function primsMST(V, adj) {
  const visited = new Array(V).fill(false);
  const minHeap = [[0, 0]]; // [wt, u]
  let mstSum = 0;

  while (minHeap.length > 0) {
    minHeap.sort((a, b) => a[0] - b[0]);
    const [wt, u] = minHeap.shift();
    if (visited[u]) continue;
    visited[u] = true;
    mstSum += wt;
    for (const [v, weight] of adj[u] || []) {
      if (!visited[v]) {
        minHeap.push([weight, v]);
      }
    }
  }
  return mstSum;
}

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
    def find(self, i):
        if self.parent[i] == i:
            return i
        self.parent[i] = self.find(self.parent[i])
        return self.parent[i]
    def union(self, i, j):
        root_i, root_j = self.find(i), self.find(j)
        if root_i != root_j:
            if self.rank[root_i] < self.rank[root_j]:
                root_i, root_j = root_j, root_i
            self.parent[root_j] = root_i
            if self.rank[root_i] == self.rank[root_j]:
                self.rank[root_i] += 1
            return True
        return False

def kruskal(V, edges):
    edges.sort(key=lambda x: x[2]) # (u, v, wt)
    dsu = DSU(V)
    mst_sum = 0
    for u, v, wt in edges:
        if dsu.union(u, v):
            mst_sum += wt
    return mst_sum

