        Collections.sort(edges);
        int[] parent = new int[V];
        for (int i = 0; i < V; i++) parent[i] = i;

        int mst = 0;
        for (Edge edge : edges) {
            int rootU = find(parent, edge.u);
            int rootV = find(parent, edge.v);
            if (rootU != rootV) {
                parent[rootU] = rootV;
                mst += edge.wt;
            }
        }
        return mst;
    }
