  }
  const tin = new Array(n).fill(-1);
  const low = new Array(n).fill(-1);
  let timer = 0;
  const bridges = [];

  function dfs(u, p) {
    tin[u] = low[u] = timer++;
    for (const v of adj[u]) {
      if (v === p) continue;
      if (tin[v] !== -1) {
        low[u] = Math.min(low[u], tin[v]);
      } else {
