        low[u] = Math.min(low[u], low[v]);
        if (low[v] > tin[u]) {
          bridges.push([u, v]);
        }
      }
    }
  }
  dfs(0, -1);
  return bridges;
}

def kosaraju_scc(V, adj):
    stack = []
    visited = [False] * V

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]: dfs1(v)
        stack.append(u)

    for i in range(V):
        if not visited[i]: dfs1(i)

    adj_rev = [[] for _ in range(V)]
    for u in range(V):
        for v in adj[u]:
            adj_rev[v].append(u)

    visited = [False] * V
    sccs = []
    def dfs2(u, comp):
        visited[u] = True
        comp.append(u)
        for v in adj_rev[u]:
            if not visited[v]: dfs2(v, comp)

    while stack:
        u = stack.pop()
        if not visited[u]:
            comp = []
            dfs2(u, comp)
            sccs.append(comp)
    return sccs

