public class KosarajuSCC {
    public List<List<Integer>> kosaraju(int V, List<List<Integer>> adj) {
        boolean[] vis = new boolean[V];
        Stack<Integer> st = new Stack<>();
        for (int i = 0; i < V; i++) if (!vis[i]) dfs1(i, adj, vis, st);

