from collections import deque

class GraphPropertiesClassifier:
    def __init__(self, V, edges, directed=False):
        self.V = V
        self.directed = directed
        self.adj = {i: [] for i in range(V)}
        for u, v in edges:
            self.adj[u].append(v)
            if not directed:
                self.adj[v].append(u)

    def count_connected_components(self):
        visited = [False] * self.V
        components = 0
        for i in range(self.V):
            if not visited[i]:
                components += 1
                queue = deque([i])
                visited[i] = True
                while queue:
                    curr = queue.popleft()
                    for neighbor in self.adj[curr]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)
        return components

    def is_bipartite(self):
        color = [-1] * self.V
        for i in range(self.V):
            if color[i] == -1:
                color[i] = 0
                queue = deque([i])
                while queue:
                    u = queue.popleft()
                    for v in self.adj[u]:
                        if color[v] == -1:
                            color[v] = 1 - color[u]
                            queue.append(v)
                        elif color[v] == color[u]:
                            return False
        return True

