public class GraphPropertiesClassifier {
    int V;
    List<List<Integer>> adj;

    public GraphPropertiesClassifier(int n, int[][] edges) {
        this.V = n;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
    }

    public boolean isBipartite() {
        int[] color = new int[V];
        Arrays.fill(color, -1);
        for (int i = 0; i < V; i++) {
            if (color[i] == -1) {
                color[i] = 0;
                Queue<Integer> q = new LinkedList<>();
                q.add(i);
                while (!q.isEmpty()) {
                    int u = q.poll();
                    for (int v : adj.get(u)) {
                        if (color[v] == -1) {
                            color[v] = 1 - color[u];
                            q.add(v);
                        } else if (color[v] == color[u]) return false;
                    }
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        GraphPropertiesClassifier g = new GraphPropertiesClassifier(5, new int[][]{{0,1}, {1,2}, {2,0}, {3,4}});
        System.out.println("Is Bipartite: " + g.isBipartite());
    }
}

