def count_components(graph, n):
    visited = [False] * n
    count = 0

    def dfs(node):
        visited[node] = True
        for nei in graph[node]:
            if not visited[nei]:
                dfs(nei)

    for i in range(n):
        if not visited[i]:
            count += 1
            dfs(i)

    return count

def dag_shortest_path(graph, topo, source):
    dist = {u: float('inf') for u in graph}
    dist[source] = 0
    for u in topo:
        if dist[u] != float('inf'):
            for v, w in graph[u]:
                dist[v] = min(dist[v], dist[u] + w)
    return dist

