vector<int> eulerianCircuit(int V, vector<vector<int>>& adj, int start) {
    stack<int> st;
    vector<int> path;
    st.push(start);
    while (!st.empty()) {
        int u = st.top();
        if (!adj[u].empty()) {
            int v = adj[u].back();
            adj[u].pop_back();
            st.push(v);
        } else {
            path.push_back(st.top());
            st.pop();
        }
    }
    reverse(path.begin(), path.end());
    return path;
}

