public class EulerianPath {
    public static List<Integer> getEulerianCircuit(List<List<Integer>> adj, int start) {
        Stack<Integer> st = new Stack<>();
        List<Integer> path = new ArrayList<>();
        st.push(start);
        while (!st.isEmpty()) {
            int u = st.peek();
            if (!adj.get(u).isEmpty()) {
                int v = adj.get(u).remove(adj.get(u).size() - 1);
                st.push(v);
            } else {
                path.add(st.pop());
            }
        }
        Collections.reverse(path);
        return path;
    }
}

