def hamiltonian_path(V, adj):
    visited = [False] * V
    path = []
    def dfs(u):
        visited[u] = True
        path.append(u)
        if len(path) == V:
            return True
        for v in adj[u]:
            if not visited[v]:
                if dfs(v): return True
        visited[u] = False
        path.pop()
        return False
    for i in range(V):
        if dfs(i): return path
    return []

