bool dfs(int u, int V, vector<vector<int>>& adj, vector<bool>& visited, vector<int>& path) {
    visited[u] = true;
    path.push_back(u);
    if (path.size() == V) return true;
    for (int v : adj[u]) {
        if (!visited[v] && dfs(v, V, adj, visited, path)) return true;
    }
    visited[u] = false;
    path.pop_back();
    return false;
}

