public class HamiltonianPath {
    public static boolean solve(int u, int V, List<List<Integer>> adj, boolean[] visited, List<Integer> path) {
        visited[u] = true;
        path.add(u);
        if (path.size() == V) return true;
        for (int v : adj.get(u)) {
            if (!visited[v] && solve(v, V, adj, visited, path)) return true;
        }
        visited[u] = false;
        path.remove(path.size() - 1);
        return false;
    }
}

