def min_path_sum(grid):
    n = len(grid[0])
    dp = [float('inf')] * n
    dp[0] = 0

    for row in grid:
        dp[0] += row[0]
        for col in range(1, n):
            dp[col] = min(dp[col], dp[col - 1]) + row[col]

    return dp[-1]

