def min_cut(s):
    n = len(s)
    palindrome = [[False] * n for _ in range(n)]

    for length in range(1, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            palindrome[l][r] = (
                s[l] == s[r] and
                (length <= 2 or palindrome[l + 1][r - 1])
            )

    dp = [0] * n

    for i in range(n):
        if palindrome[0][i]:
            dp[i] = 0
        else:
            dp[i] = i
            for j in range(1, i + 1):
                if palindrome[j][i]:
                    dp[i] = min(dp[i], dp[j - 1] + 1)

    return dp[-1] if n else 0

