int rodCutting(vector<int>& prices, int n) {
    vector<int> dp(n + 1, 0);

    for (int length = 1; length <= n; length++) {
        for (int cut = 1; cut <= length; cut++) {
            dp[length] = max(
                dp[length],
                prices[cut - 1] + dp[length - cut]
            );
        }
    }

    return dp[n];
}

class Solution {
    public int rodCutting(int[] prices, int n) {
        int[] dp = new int[n + 1];

        for (int length = 1; length <= n; length++) {
            for (int cut = 1; cut <= length; cut++) {
                dp[length] = Math.max(
                    dp[length],
                    prices[cut - 1] + dp[length - cut]
                );
            }
        }

        return dp[n];
    }
}

