int maxProfit(vector<int>& prices) {
    int cash = 0;
    int hold = INT_MIN;

    for (int price : prices) {
        cash = max(cash, hold + price);
        hold = max(hold, -price);
    }

    return cash;
}

class Solution {
    public int maxProfit(int[] prices) {
        int cash = 0;
        int hold = Integer.MIN_VALUE;

        for (int price : prices) {
            cash = Math.max(cash, hold + price);
            hold = Math.max(hold, -price);
        }

        return cash;
    }
}

def rob(root):
    def dfs(node):
        if not node:
            return (0, 0)

        left_skip, left_take = dfs(node.left)
        right_skip, right_take = dfs(node.right)

        take = node.val + left_skip + right_skip
        skip = max(left_skip, left_take) + max(right_skip, right_take)

        return (skip, take)

    skip, take = dfs(root)
    return max(skip, take)

