vector<long long> dagShortestPath(int n, vector<tuple<int,int,int>>& edges, int source) {
    vector<vector<pair<int,int>>> graph(n);
    vector<int> indegree(n);

    for (auto [u,v,w] : edges) {
        graph[u].push_back({v,w});
        indegree[v]++;
    }

    queue<int> q;
    for (int i = 0; i < n; i++)
        if (indegree[i] == 0) q.push(i);

    vector<int> order;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u);

        for (auto [v,w] : graph[u]) {
            if (--indegree[v] == 0) q.push(v);
        }
    }

    const long long INF = 1e18;
    vector<long long> dp(n, INF);
    dp[source] = 0;

    for (int u : order) {
        if (dp[u] == INF) continue;

        for (auto [v,w] : graph[u]) {
            dp[v] = min(dp[v], dp[u] + w);
        }
    }

    return dp;
}

class Solution {
    public long[] dagShortestPath(int n, int[][] edges, int source) {
        List<int[]>[] graph = new ArrayList[n];
        int[] indegree = new int[n];

        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();

        for (int[] edge : edges) {
            graph[edge[0]].add(new int[]{edge[1], edge[2]});
            indegree[edge[1]]++;
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) queue.offer(i);
        }

        List<Integer> order = new ArrayList<>();

        while (!queue.isEmpty()) {
            int u = queue.poll();
            order.add(u);

            for (int[] edge : graph[u]) {
                if (--indegree[edge[0]] == 0) queue.offer(edge[0]);
            }
        }

        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n];
        Arrays.fill(dp, INF);
        dp[source] = 0;

        for (int u : order) {
            if (dp[u] == INF) continue;

            for (int[] edge : graph[u]) {
                int v = edge[0];
                int w = edge[1];
                dp[v] = Math.min(dp[v], dp[u] + w);
            }
        }

        return dp;
    }
}

def tsp(dist):
    n = len(dist)
    INF = float('inf')
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0

    for mask in range(1 << n):
        for u in range(n):
            if not (mask & (1 << u)):
                continue

            for v in range(n):
                if mask & (1 << v):
                    continue

                next_mask = mask | (1 << v)
                dp[next_mask][v] = min(
                    dp[next_mask][v],
                    dp[mask][u] + dist[u][v]
                )

    full = (1 << n) - 1
    return min(dp[full][i] + dist[i][0] for i in range(n))

