    const int INF = 1e9;
    int total = 1 << n;

    vector<vector<int>> dp(total, vector<int>(n, INF));
    dp[1][0] = 0;

    for (int mask = 0; mask < total; mask++) {
        for (int u = 0; u < n; u++) {
            if (!(mask & (1 << u))) continue;

            for (int v = 0; v < n; v++) {
                if (mask & (1 << v)) continue;

                int nextMask = mask | (1 << v);
                dp[nextMask][v] = min(
                    dp[nextMask][v],
                    dp[mask][u] + dist[u][v]
                );
            }
        }
    }

    int full = total - 1;
    int answer = INF;

    for (int i = 0; i < n; i++) {
        answer = min(answer, dp[full][i] + dist[i][0]);
    }

    return answer;
}

class Solution {
    public int tsp(int[][] dist) {
        int n = dist.length;
        int total = 1 << n;
        int INF = 1_000_000_000;

        int[][] dp = new int[total][n];
        for (int[] row : dp) Arrays.fill(row, INF);

        dp[1][0] = 0;

        for (int mask = 0; mask < total; mask++) {
            for (int u = 0; u < n; u++) {
                if ((mask & (1 << u)) == 0) continue;

                for (int v = 0; v < n; v++) {
                    if ((mask & (1 << v)) != 0) continue;

                    int nextMask = mask | (1 << v);
                    dp[nextMask][v] = Math.min(
                        dp[nextMask][v],
                        dp[mask][u] + dist[u][v]
                    );
                }
            }
        }

        int full = total - 1;
        int answer = INF;

        for (int i = 0; i < n; i++) {
            answer = Math.min(answer, dp[full][i] + dist[i][0]);
