string s;
long long memo[20][200][2];
bool vis[20][200][2];

long long solve(int pos, int sum, int tight) {
    if (pos == s.size()) return sum == 0;

    if (vis[pos][sum][tight]) return memo[pos][sum][tight];
    vis[pos][sum][tight] = true;

    int limit = tight ? s[pos] - '0' : 9;
    long long ans = 0;

    for (int digit = 0; digit <= limit && digit <= sum; digit++) {
        ans += solve(
            pos + 1,
            sum - digit,
            tight && digit == limit
        );
    }

    return memo[pos][sum][tight] = ans;
}

long long countDigitSum(long long n, int target) {
    s = to_string(n);
    memset(vis, false, sizeof(vis));
    return solve(0, target, 1);
}

class Solution {
    private String s;
    private long[][][] memo;
    private boolean[][][] seen;

    private long solve(int pos, int sum, int tight, int target) {
        if (pos == s.length()) return sum == target ? 1 : 0;

        if (seen[pos][sum][tight]) return memo[pos][sum][tight];
        seen[pos][sum][tight] = true;

        int limit = tight == 1 ? s.charAt(pos) - '0' : 9;
        long answer = 0;

        for (int digit = 0; digit <= limit; digit++) {
            answer += solve(
                pos + 1,
                sum + digit,
                tight == 1 && digit == limit ? 1 : 0,
                target
            );
        }

        return memo[pos][sum][tight] = answer;
    }

    public long countDigitSum(long n, int target) {
        s = String.valueOf(n);
        memo = new long[s.length()][target + 1][2];
        seen = new boolean[s.length()][target + 1][2];
        return solve(0, 0, 1, target);
    }
}

