void dfs1(int u, int parent, vector<vector<int>>& graph,
          vector<int>& subtree, vector<long long>& answer) {
    subtree[u] = 1;

    for (int v : graph[u]) {
        if (v == parent) continue;

        dfs1(v, u, graph, subtree, answer);
        subtree[u] += subtree[v];
        answer[0] += subtree[v];
    }
}

void dfs2(int u, int parent, vector<vector<int>>& graph,
          vector<int>& subtree, vector<long long>& answer, int n) {
    for (int v : graph[u]) {
        if (v == parent) continue;

        answer[v] = answer[u] + n - 2LL * subtree[v];
        dfs2(v, u, graph, subtree, answer, n);
    }
}

class Solution {
    private int[] subtree;
    private long[] answer;
    private List<Integer>[] graph;
    private int n;

    private void dfs1(int u, int parent) {
        subtree[u] = 1;

        for (int v : graph[u]) {
            if (v == parent) continue;

            dfs1(v, u);
            subtree[u] += subtree[v];
            answer[0] += subtree[v];
        }
    }

    private void dfs2(int u, int parent) {
        for (int v : graph[u]) {
            if (v == parent) continue;

            answer[v] = answer[u] + n - 2L * subtree[v];
            dfs2(v, u);
        }
    }
}

def interval_dp(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for left in range(n - length + 1):
            right = left + length - 1

            for mid in range(left, right):
                candidate = (
                    dp[left][mid] +
                    dp[mid + 1][right]
                )
                dp[left][right] = max(dp[left][right], candidate)

    return dp[0][n - 1]

