int intervalDP(vector<int>& arr) {
    int n = arr.size();
    vector<vector<int>> dp(n, vector<int>(n));

    for (int len = 2; len <= n; len++) {
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;

            for (int mid = l; mid < r; mid++) {
                dp[l][r] = max(
                    dp[l][r],
                    dp[l][mid] + dp[mid + 1][r]
                );
            }
        }
    }

    return dp[0][n - 1];
}

