        int mid = (start + end) / 2;
        return query(2 * node + 1, start, mid, l, r) + query(2 * node + 2, mid + 1, end, l, r);
    }
    public LazySegmentTree(int[] nums) {
        n = nums.length;
        tree = new long[4 * n];
        lazy = new long[4 * n];
    }
    public void updateRange(int l, int r, long val) { update(0, 0, n - 1, l, r, val); }
    public long queryRange(int l, int r) { return query(0, 0, n - 1, l, r); }
}

class LazySegmentTree {
  constructor(nums) {
    this.n = nums.length;
    this.tree = new Array(4 * this.n).fill(0);
    this.lazy = new Array(4 * this.n).fill(0);
  }
  _push(node, start, end) {
    if (this.lazy[node] !== 0) {
      this.tree[node] += (end - start + 1) * this.lazy[node];
      if (start !== end) {
        this.lazy[2 * node + 1] += this.lazy[node];
        this.lazy[2 * node + 2] += this.lazy[node];
      }
      this.lazy[node] = 0;
    }
  }
  updateRange(l, r, val) {
    this._update(0, 0, this.n - 1, l, r, val);
  }
  _update(node, start, end, l, r, val) {
    this._push(node, start, end);
    if (r < start || end < l) return;
    if (l <= start && end <= r) {
      this.lazy[node] += val;
      this._push(node, start, end);
      return;
    }
    const mid = Math.floor((start + end) / 2);
    this._update(2 * node + 1, start, mid, l, r, val);
    this._update(2 * node + 2, mid + 1, end, l, r, val);
    this.tree[node] = this.tree[2 * node + 1] + this.tree[2 * node + 2];
  }
  queryRange(l, r) {
    return this._query(0, 0, this.n - 1, l, r);
  }
  _query(node, start, end, l, r) {
    this._push(node, start, end);
    if (r < start || end < l) return 0;
    if (l <= start && end <= r) return this.tree[node];
    const mid = Math.floor((start + end) / 2);
    return this._query(2 * node + 1, start, mid, l, r) + this._query(2 * node + 2, mid + 1, end, l, r);
  }
}

class FenwickTree:
    def __init__(self, size: int):
        self.n = size
        self.tree = [0] * (size + 1)

    def update(self, idx: int, delta: int):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & (-idx)

    def query(self, idx: int) -> int:
        s = 0
        while idx > 0:
            s += self.tree[idx]
            idx -= idx & (-idx)
        return s

    def queryRange(self, l: int, r: int) -> int:
        return self.query(r) - self.query(l - 1)

