class RangeBIT:
    def __init__(self, size: int):
        self.n = size
        self.b1 = [0] * (size + 1)
        self.b2 = [0] * (size + 1)

    def _add(self, b, idx, val):
        while idx <= self.n:
            b[idx] += val
            idx += idx & (-idx)

    def _query(self, b, idx):
        s = 0
        while idx > 0:
            s += b[idx]
            idx -= idx & (-idx)
        return s

    def updateRange(self, l: int, r: int, val: int):
        self._add(self.b1, l, val)
        self._add(self.b1, r + 1, -val)
        self._add(self.b2, l, val * (l - 1))
        self._add(self.b2, r + 1, -val * r)

    def prefixSum(self, idx: int) -> int:
        return self._query(self.b1, idx) * idx - self._query(self.b2, idx)

    def queryRange(self, l: int, r: int) -> int:
        return self.prefixSum(r) - self.prefixSum(l - 1)

