class SparseTableMin:
    def __init__(self, arr: list[int]):
        self.n = len(arr)
        if self.n == 0: return
        self.K = int(math.log2(self.n)) + 1
        self.table = [[0] * self.K for _ in range(self.n)]
        for i in range(self.n):
            self.table[i][0] = arr[i]
        for j in range(1, self.K):
            for i in range(self.n - (1 << j) + 1):
                self.table[i][j] = min(self.table[i][j - 1], self.table[i + (1 << (j - 1))][j - 1])

    def queryMin(self, l: int, r: int) -> int:
        length = r - l + 1
        k = int(math.log2(length))
        return min(self.table[l][k], self.table[r - (1 << k) + 1][k])

