class AVLTree {
  getHeight(n) { return n ? n.height : 0; }
  getBalance(n) { return n ? this.getHeight(n.left) - this.getHeight(n.right) : 0; }

  rightRotate(y) {
    const x = y.left, T2 = x.right;
    x.right = y; y.left = T2;
    y.height = Math.max(this.getHeight(y.left), this.getHeight(y.right)) + 1;
    x.height = Math.max(this.getHeight(x.left), this.getHeight(x.right)) + 1;
    return x;
  }

  leftRotate(x) {
    const y = x.right, T2 = y.left;
    y.left = x; x.right = T2;
    x.height = Math.max(this.getHeight(x.left), this.getHeight(x.right)) + 1;
    y.height = Math.max(this.getHeight(y.left), this.getHeight(y.right)) + 1;
    return y;
  }

  insert(node, val) {
    if (!node) return new AVLNode(val);
    if (val < node.val) node.left = this.insert(node.left, val);
    else if (val > node.val) node.right = this.insert(node.right, val);
    else return node;

    node.height = Math.max(this.getHeight(node.left), this.getHeight(node.right)) + 1;
    const balance = this.getBalance(node);

    if (balance > 1 && val < node.left.val) return this.rightRotate(node);
    if (balance < -1 && val > node.right.val) return this.leftRotate(node);
    if (balance > 1 && val > node.left.val) {
      node.left = this.leftRotate(node.left);
      return this.rightRotate(node);
    }
    if (balance < -1 && val < node.right.val) {
      node.right = this.rightRotate(node.right);
      return this.leftRotate(node);
    }
    return node;
  }
}

