def count_divisible(n: int, primes: list[int]) -> int:
    k = len(primes)
    count = 0
    for mask in range(1, 1 << k):
        prod = 1
        bits = 0
        for i in range(k):
            if (mask >> i) & 1:
                prod *= primes[i]
                bits += 1
        if bits % 2 == 1:
            count += n // prod
        else:
            count -= n // prod
    return count

