int minimaxAlphaBeta(int depth, int nodeIdx, bool isMax, vector<int>& scores, int alpha, int beta, int maxDepth) {
    if (depth == maxDepth) return scores[nodeIdx];
    if (isMax) {
        int best = INT_MIN;
        for (int i = 0; i < 2; i++) {
            int val = minimaxAlphaBeta(depth + 1, nodeIdx * 2 + i, false, scores, alpha, beta, maxDepth);
            best = max(best, val);
            alpha = max(alpha, best);
            if (beta <= alpha) break; // Beta cutoff
        }
        return best;
    } else {
        int best = INT_MAX;
        for (int i = 0; i < 2; i++) {
            int val = minimaxAlphaBeta(depth + 1, nodeIdx * 2 + i, true, scores, alpha, beta, maxDepth);
            best = min(best, val);
            beta = min(beta, best);
            if (beta <= alpha) break; // Alpha cutoff
        }
        return best;
    }
}

public class Solution {
    public static int minimaxAlphaBeta(int depth, int nodeIdx, boolean isMax, int[] scores, int alpha, int beta, int maxDepth) {
        if (depth == maxDepth) return scores[nodeIdx];
        if (isMax) {
            int best = Integer.MIN_VALUE;
            for (int i = 0; i < 2; i++) {
                int val = minimaxAlphaBeta(depth + 1, nodeIdx * 2 + i, false, scores, alpha, beta, maxDepth);
                best = Math.max(best, val);
                alpha = Math.max(alpha, best);
                if (beta <= alpha) break;
            }
            return best;
        } else {
            int best = Integer.MAX_VALUE;
            for (int i = 0; i < 2; i++) {
                int val = minimaxAlphaBeta(depth + 1, nodeIdx * 2 + i, true, scores, alpha, beta, maxDepth);
                best = Math.min(best, val);
                beta = Math.min(beta, best);
                if (beta <= alpha) break;
            }
            return best;
        }
    }
}

function minimaxAlphaBeta(depth, nodeIdx, isMax, scores, alpha, beta, maxDepth) {
  if (depth === maxDepth) return scores[nodeIdx];
