def orientation(a, b, c):
    cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    if cross > 0:
        return 1      # counter-clockwise
    if cross < 0:
        return -1     # clockwise
    return 0          # collinear

