double polygonArea(vector<pair<long long,long long>> p) {
    long long total = 0;
    int n = p.size();

    for (int i = 0; i < n; i++) {
        auto [x1,y1] = p[i];
        auto [x2,y2] = p[(i+1)%n];
        total += x1*y2 - y1*x2;
    }

    return abs(total) / 2.0;
}

static double polygonArea(long[][] p) {
    long total = 0;
    int n = p.length;

    for (int i = 0; i < n; i++) {
        long[] a = p[i];
        long[] b = p[(i+1)%n];
        total += a[0]*b[1] - a[1]*b[0];
    }

    return Math.abs(total) / 2.0;
}

double perimeter(vector<pair<double,double>> p) {
    double ans = 0;
    int n = p.size();

    for (int i=0; i<n; i++) {
        double dx = p[i].first - p[(i+1)%n].first;
        double dy = p[i].second - p[(i+1)%n].second;
        ans += hypot(dx,dy);
    }
    return ans;
}

static double perimeter(double[][] p) {
    double ans = 0;
