    for (int i=0; i<n; i++) {
        double dx = p[i][0] - p[(i+1)%n][0];
        double dy = p[i][1] - p[(i+1)%n][1];
        ans += Math.hypot(dx, dy);
    }
    return ans;
}

def point_in_polygon(point, polygon):
    x, y = point
    inside = False
    n = len(polygon)

    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i + 1) % n]

        if (y1 > y) != (y2 > y):
            x_intersection = x1 + (y-y1) * (x2-x1) / (y2-y1)
            if x < x_intersection:
                inside = not inside

    return inside

