        auto [x1,y1] = poly[i];
        auto [x2,y2] = poly[(i+1)%n];

        if ((y1 > p.second) != (y2 > p.second)) {
            double x = x1 + (p.second-y1)*(x2-x1)/(y2-y1);
            if (p.first < x) inside = !inside;
