static List<long[]> hull(List<long[]> p) {
    p.sort((a,b)->a[0]!=b[0] ? Long.compare(a[0],b[0]) : Long.compare(a[1],b[1]));

    List<long[]> lo=new ArrayList<>(), up=new ArrayList<>();
    for(long[] x:p){
        while(lo.size()>=2 && cross(lo.get(lo.size()-2),lo.get(lo.size()-1),x)<=0)
            lo.remove(lo.size()-1);
        lo.add(x);
    }

    for(int i=p.size()-1;i>=0;i--){
        long[] x=p.get(i);
        while(up.size()>=2 && cross(up.get(up.size()-2),up.get(up.size()-1),x)<=0)
            up.remove(up.size()-1);
        up.add(x);
    }

    lo.remove(lo.size()-1);
    up.remove(up.size()-1);
    lo.addAll(up);
    return lo;
}

def cross(a,b,c):
