def is_convex(p):
    n=len(p)
    sign=0

    for i in range(n):
        c=cross(p[i],p[(i+1)%n],p[(i+2)%n])
        if c != 0:
            if sign == 0:
                sign = 1 if c > 0 else -1
            elif (c > 0) != (sign > 0):
                return False
    return True

bool isConvex(vector<pair<long long,long long>> p) {
    int n=p.size(), sign=0;

    auto cross=[](auto a,auto b,auto c){
        return (b.first-a.first)*(c.second-a.second)
             -(b.second-a.second)*(c.first-a.first);
    };

    for(int i=0;i<n;i++){
        long long c=cross(p[i],p[(i+1)%n],p[(i+2)%n]);
        if(c==0) continue;
        int s=c>0?1:-1;
        if(sign==0) sign=s;
        else if(sign!=s) return false;
    }
    return true;
}

