def closest_pair(points):
    points = sorted(points)

    def dist2(a,b):
        return (a[0]-b[0])**2 + (a[1]-b[1])**2

    def solve(p):
        n=len(p)
        if n<=3:
            return min((dist2(p[i],p[j]) for i in range(n) for j in range(i+1,n)), default=float('inf'))

        mid=n//2
        xmid=p[mid][0]
        d=min(solve(p[:mid]),solve(p[mid:]))

        strip=[q for q in p if (q[0]-xmid)**2 < d]
        strip.sort(key=lambda q:q[1])

        for i in range(len(strip)):
            for j in range(i+1,min(i+8,len(strip))):
                d=min(d,dist2(strip[i],strip[j]))
        return d

    return solve(points)

using P=pair<long long,long long>;

long long d2(P a,P b){
    long long x=a.first-b.first,y=a.second-b.second;
    return x*x+y*y;
}

long long closest(vector<P>& p,int l,int r){
    if(r-l<=3){
        long long ans=LLONG_MAX;
        for(int i=l;i<r;i++) for(int j=i+1;j<r;j++) ans=min(ans,d2(p[i],p[j]));
        return ans;
    }

    int m=(l+r)/2;
    long long d=min(closest(p,l,m),closest(p,m,r));
    long long midx=p[m].first;
    vector<P> strip;

    for(int i=l;i<r;i++)
        if((p[i].first-midx)*(p[i].first-midx)<d) strip.push_back(p[i]);

    sort(strip.begin(),strip.end(),[](P a,P b){return a.second<b.second;});
    for(int i=0;i<strip.size();i++)
        for(int j=i+1;j<strip.size() && j<i+8;j++)
            d=min(d,d2(strip[i],strip[j]));

    return d;
}

static long d2(long[] a,long[] b){
    long x=a[0]-b[0],y=a[1]-b[1];
    return x*x+y*y;
}

static long closest(long[][] p,int l,int r){
    if(r-l<=3){
        long ans=Long.MAX_VALUE;
        for(int i=l;i<r;i++) for(int j=i+1;j<r;j++) ans=Math.min(ans,d2(p[i],p[j]));
        return ans;
    }

    int m=(l+r)/2;
    long d=Math.min(closest(p,l,m),closest(p,m,r));
    long mid=p[m][0];
    ArrayList<long[]> strip=new ArrayList<>();

    for(int i=l;i<r;i++)
        if((p[i][0]-mid)*(p[i][0]-mid)<d) strip.add(p[i]);

    strip.sort(Comparator.comparingLong(a->a[1]));
    for(int i=0;i<strip.size();i++)
        for(int j=i+1;j<strip.size() && j<i+8;j++)
            d=Math.min(d,d2(strip.get(i),strip.get(j)));

    return d;
}

