string circleRelation(pair<double,double> a,double r1,
                      pair<double,double> b,double r2) {
    double d=hypot(a.first-b.first,a.second-b.second);
    const double EPS=1e-9;
    if(d>r1+r2+EPS) return "separate";
    if(d<fabs(r1-r2)-EPS) return "one inside another";
    if(fabs(d-(r1+r2))<EPS || fabs(d-fabs(r1-r2))<EPS) return "touching";
    return "two intersections";
}

static String circleRelation(double[] a,double r1,double[] b,double r2) {
    double d=Math.hypot(a[0]-b[0],a[1]-b[1]);
    double eps=1e-9;
    if(d>r1+r2+eps) return "separate";
    if(d<Math.abs(r1-r2)-eps) return "one inside another";
    if(Math.abs(d-r1-r2)<eps || Math.abs(d-Math.abs(r1-r2))<eps)
        return "touching";
    return "two intersections";
}

