    int n=p.size();

    for(int i=0;i<n;i++) {
        auto a=p[i],b=p[(i+1)%n];
        double c=a.first*b.second-b.first*a.second;
        A2+=c;
        Cx+=(a.first+b.first)*c;
        Cy+=(a.second+b.second)*c;
    }

    return {Cx/(3*A2),Cy/(3*A2)};
}

