        double c=a[0]*b[1]-b[0]*a[1];
        A2+=c;
        Cx+=(a[0]+b[0])*c;
        Cy+=(a[1]+b[1])*c;
    }

    return new double[]{Cx/(3*A2),Cy/(3*A2)};
}

bool insideConvexPolygon(vector<pair<long long,long long>> p,
                           pair<long long,long long> q) {
    bool pos=false,neg=false;
    int n=p.size();

    for(int i=0;i<n;i++) {
        auto a=p[i],b=p[(i+1)%n];
        long long c=(b.first-a.first)*(q.second-a.second)
                   -(b.second-a.second)*(q.first-a.first);
        pos|=c>0;
        neg|=c<0;
    }
    return !(pos&&neg);
}

static boolean insideConvexPolygon(long[][] p,long[] q) {
    boolean pos=false,neg=false;
    int n=p.length;

    for(int i=0;i<n;i++) {
        long[] a=p[i],b=p[(i+1)%n];
        long c=(b[0]-a[0])*(q[1]-a[1])-(b[1]-a[1])*(q[0]-a[0]);
        if(c>0) pos=true;
        if(c<0) neg=true;
    }
    return !(pos&&neg);
}

