int maxOverlap(vector<pair<int,int>> intervals) {
    vector<pair<int,int>> events;
    for(auto [l,r]:intervals) {
        events.push_back({l,1});
        events.push_back({r,-1});
    }

    sort(events.begin(),events.end());
    int active=0,ans=0;
    for(auto [x,d]:events) {
        active+=d;
        ans=max(ans,active);
    }
    return ans;
}

static int maxOverlap(int[][] intervals) {
    List<int[]> events=new ArrayList<>();
    for(int[] x:intervals) {
        events.add(new int[]{x[0],1});
        events.add(new int[]{x[1],-1});
    }

    events.sort((a,b)->a[0]!=b[0]
        ? Integer.compare(a[0],b[0]) : Integer.compare(a[1],b[1]));

    int active=0,ans=0;
    for(int[] e:events) {
        active+=e[1];
        ans=Math.max(ans,active);
    }
    return ans;
}

