public class SuffixArray {
    public static int[] buildSuffixArray(String s) {
        s += "$";
        int n = s.length();
        Integer[] sa = new Integer[n];
        int[] rank = new int[n], tmp = new int[n];
        for (int i = 0; i < n; i++) { sa[i] = i; rank[i] = s.charAt(i); }
        for (int k = 1; k < n; k <<= 1) {
            final int step = k, r[] = rank;
            Arrays.sort(sa, (i, j) -> {
                if (r[i] != r[j]) return Integer.compare(r[i], r[j]);
                int ri = (i + step < n) ? r[i + step] : -1;
                int rj = (j + step < n) ? r[j + step] : -1;
                return Integer.compare(ri, rj);
            });
            tmp[sa[0]] = 0;
            for (int i = 1; i < n; i++) {
                int prev = sa[i - 1], curr = sa[i];
                boolean diff = r[prev] != r[curr] || ((prev + step < n ? r[prev + step] : -1) != (curr + step < n ? r[curr + step] : -1));
                tmp[curr] = tmp[prev] + (diff ? 1 : 0);
            }
            System.arraycopy(tmp, 0, rank, 0, n);
            if (rank[sa[n - 1]] == n - 1) break;
        }
        int[] res = new int[n];
        for (int i = 0; i < n; i++) res[i] = sa[i];
        return res;
    }
}

function buildSuffixArray(s) {
  s += '$';
  const n = s.length;
  let sa = Array.from({ length: n }, (_, i) => i);
  let rank = s.split('').map(c => c.charCodeAt(0));
  let tmp = new Array(n);
  for (let k = 1; k < n; k *= 2) {
    sa.sort((i, j) => {
      if (rank[i] !== rank[j]) return rank[i] - rank[j];
      let ri = i + k < n ? rank[i + k] : -1;
      let rj = j + k < n ? rank[j + k] : -1;
      return ri - rj;
    });
    tmp[sa[0]] = 0;
    for (let i = 1; i < n; i++) {
      let prev = sa[i - 1], curr = sa[i];
      let riPrev = prev + k < n ? rank[prev + k] : -1;
      let riCurr = curr + k < n ? rank[curr + k] : -1;
      let diff = rank[prev] !== rank[curr] || riPrev !== riCurr;
      tmp[curr] = tmp[prev] + (diff ? 1 : 0);
    }
    rank = [...tmp];
    if (rank[sa[n - 1]] === n - 1) break;
  }
  return sa;
}

def build_lcp_array(s: str, sa: list[int]) -> list[int]:
    n = len(s)
    rank = [0] * n
    for i in range(n):
        rank[sa[i]] = i
    lcp = [0] * n
    h = 0
    for i in range(n):
        if rank[i] > 0:
            j = sa[rank[i] - 1]
            while i + h < n and j + h < n and s[i + h] == s[j + h]:
                h += 1
            lcp[rank[i]] = h
            if h > 0:
                h -= 1
    return lcp

