def rabin_karp(text: str, pattern: str) -> list[int]:
    n, m = len(text), len(pattern)
    if m > n: return []
    p, mod = 31, 1_000_000_007
    p_pow = 1
    for _ in range(m - 1):
        p_pow = (p_pow * p) % mod
    p_hash = 0
    t_hash = 0
    for i in range(m):
        p_hash = (p_hash * p + ord(pattern[i])) % mod
        t_hash = (t_hash * p + ord(text[i])) % mod
    matches = []
    for i in range(n - m + 1):
        if p_hash == t_hash and text[i : i + m] == pattern:
            matches.append(i)
        if i < n - m:
            t_hash = (t_hash - ord(text[i]) * p_pow) % mod
            t_hash = (t_hash * p + ord(text[i + m])) % mod
            if t_hash < 0:
                t_hash += mod
    return matches

