struct Node {
    map<char, int> next;
    int fail = 0;
    vector<int> out;
};

class AhoCorasick {
    vector<Node> trie;
public:
    AhoCorasick() { trie.push_back(Node()); }
    void insert(string pattern, int id) {
        int node = 0;
        for (char c : pattern) {
            if (!trie[node].next.count(c)) {
                trie[node].next[c] = trie.size();
                trie.push_back(Node());
            }
            node = trie[node].next[c];
        }
        trie[node].out.push_back(id);
    }
    void build() {
        queue<int> q;
        for (auto& [c, nxt] : trie[0].next) q.push(nxt);
        while (!q.empty()) {
            int curr = q.front(); q.pop();
            for (auto& [c, nxt] : trie[curr].next) {
                int f = trie[curr].fail;
                while (f && !trie[f].next.count(c)) f = trie[f].fail;
                trie[nxt].fail = trie[f].next.count(c) ? trie[f].next[c] : 0;
                for (int pid : trie[trie[nxt].fail].out) trie[nxt].out.push_back(pid);
                q.push(nxt);
            }
        }
    }
};

