class ACNode {
    Map<Character, Integer> next = new HashMap<>();
    int fail = 0;
    List<Integer> out = new ArrayList<>();
}

public class AhoCorasick {
    List<ACNode> trie = new ArrayList<>();
    public AhoCorasick() { trie.add(new ACNode()); }
    public void insert(String pattern, int id) {
        int node = 0;
        for (char c : pattern.toCharArray()) {
            if (!trie.get(node).next.containsKey(c)) {
                trie.get(node).next.put(c, trie.size());
                trie.add(new ACNode());
            }
            node = trie.get(node).next.get(c);
        }
        trie.get(node).out.add(id);
    }
    public void build() {
        Queue<Integer> q = new LinkedList<>();
        for (int nxt : trie.get(0).next.values()) q.add(nxt);
        while (!q.isEmpty()) {
            int curr = q.poll();
            for (var entry : trie.get(curr).next.entrySet()) {
                char c = entry.getKey(); int nxt = entry.getValue();
                int f = trie.get(curr).fail;
                while (f > 0 && !trie.get(f).next.containsKey(c)) f = trie.get(f).fail;
                trie.get(nxt).fail = trie.get(f).next.getOrDefault(c, 0);
                trie.get(nxt).out.addAll(trie.get(trie.get(nxt).fail).out);
                q.add(nxt);
            }
        }
    }
}

class AhoCorasick {
  constructor() {
    this.trie = [{ next: {}, fail: 0, out: [] }];
  }
  insert(pattern, id) {
    let node = 0;
    for (const c of pattern) {
      if (!(c in this.trie[node].next)) {
        this.trie[node].next[c] = this.trie.length;
        this.trie.push({ next: {}, fail: 0, out: [] });
      }
      node = this.trie[node].next[c];
    }
    this.trie[node].out.push(id);
  }
  build() {
    const q = [];
    for (const nxt of Object.values(this.trie[0].next)) q.push(nxt);
    while (q.length > 0) {
      let curr = q.shift();
      for (const [c, nxt] of Object.entries(this.trie[curr].next)) {
        let f = this.trie[curr].fail;
        while (f > 0 && !(c in this.trie[f].next)) f = this.trie[f].fail;
        this.trie[nxt].fail = this.trie[f].next[c] || 0;
        this.trie[nxt].out.push(...this.trie[this.trie[nxt].fail].out);
        q.push(nxt);
      }
    }
  }
}

def boyer_moore_search(text: str, pattern: str) -> list[int]:
    n, m = len(text), len(pattern)
    if m == 0 or m > n: return []
    bad_char = {}
    for i in range(m):
        bad_char[pattern[i]] = i
    matches = []
    s = 0
    while s <= n - m:
        j = m - 1
        while j >= 0 and pattern[j] == text[s + j]:
            j -= 1
        if j < 0:
            matches.append(s)
            s += (m - bad_char.get(text[s + m], -1)) if s + m < n else 1
        else:
            s += max(1, j - bad_char.get(text[s + j], -1))
    return matches

