pair<string, vector<int>> manacher(string s) {
    string t = "^#";
    for (char ch : s) { t += ch; t += "#"; }
    t += "$";
    int n = t.length();
    vector<int> p(n, 0);
    int c = 0, r = 0;
    for (int i = 1; i < n - 1; i++) {
        int iMirror = 2 * c - i;
        if (r > i) p[i] = min(r - i, p[iMirror]);
        while (t[i + 1 + p[i]] == t[i - 1 - p[i]]) p[i]++;
        if (i + p[i] > r) {
            c = i;
            r = i + p[i];
        }
    }
    int maxLen = 0, centerIdx = 0;
    for (int i = 1; i < n - 1; i++) {
        if (p[i] > maxLen) { maxLen = p[i]; centerIdx = i; }
    }
    int start = (centerIdx - maxLen) / 2;
    return {s.substr(start, maxLen), p};
}

public class Manacher {
    public static String longestPalindrome(String s) {
        StringBuilder sb = new StringBuilder("^#");
        for (char ch : s.toCharArray()) sb.append(ch).append("#");
        sb.append("$");
        String t = sb.toString();
        int n = t.length();
        int[] p = new int[n];
        int c = 0, r = 0;
        for (int i = 1; i < n - 1; i++) {
            int iMirror = 2 * c - i;
            if (r > i) p[i] = Math.min(r - i, p[iMirror]);
            while (t.charAt(i + 1 + p[i]) == t.charAt(i - 1 - p[i])) p[i]++;
            if (i + p[i] > r) {
                c = i;
                r = i + p[i];
            }
        }
        int maxLen = 0, centerIdx = 0;
        for (int i = 1; i < n - 1; i++) {
            if (p[i] > maxLen) { maxLen = p[i]; centerIdx = i; }
        }
        int start = (centerIdx - maxLen) / 2;
        return s.substring(start, start + maxLen);
