class Item:
    def __init__(self, val, wt):
        self.val = val
        self.wt = wt

def fractionalKnapsack(W: float, items: list[Item]) -> float:
    items.sort(key=lambda x: x.val / x.wt, reverse=True)
    total_val = 0.0
    for item in items:
        if W >= item.wt:
            W -= item.wt
            total_val += item.val
        else:
            total_val += item.val * (W / item.wt)
            break
    return total_val

