}

double fractionalKnapsack(int W, vector<Item>& items) {
    sort(items.begin(), items.end(), cmp);
    double totalVal = 0.0;
    for (auto& item : items) {
        if (W >= item.weight) {
            W -= item.weight;
            totalVal += item.value;
        } else {
            totalVal += item.value * ((double)W / item.weight);
            break;
        }
    }
    return totalVal;
}

