function fractionalKnapsack(W, items) {
  items.sort((a, b) => (b.value / b.weight) - (a.value / a.weight));
  let totalVal = 0.0;
  for (const item of items) {
    if (W >= item.weight) {
      W -= item.weight;
      totalVal += item.value;
    } else {
      totalVal += item.value * (W / item.weight);
      break;
    }
  }
  return totalVal;
}

