def JobScheduling(jobs: list[Job]) -> list[int]:
    jobs.sort(key=lambda x: x.profit, reverse=True)
    max_d = max(job.deadline for job in jobs)
    slots = [-1] * (max_d + 1)
    count = total_profit = 0
    for job in jobs:
        for r in range(job.deadline, 0, -1):
            if slots[r] == -1:
                slots[r] = job.id
                count += 1
                total_profit += job.profit
                break
    return [count, total_profit]

