        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int w = curr[0], u = curr[1];
            if (visited[u]) continue;
            visited[u] = true;
            mstWeight += w;
            count++;
            if (count == V) break;
            for (int[] edge : adj.get(u)) {
