        for (int c = 0; c < n; c++) {
            if (cols.count(c) || posDiag.count(r + c) || negDiag.count(r - c)) continue;
            cols.insert(c); posDiag.insert(r + c); negDiag.insert(r - c);
            board[r][c] = 'Q';
            backtrack(r + 1, n, board);
            cols.erase(c); posDiag.erase(r + c); negDiag.erase(r - c);
            board[r][c] = '.';
        }
    }
