        if (k == word.size()) return true;
        if (r < 0 || r >= m || c < 0 || c >= n || board[r][c] != word[k]) return false;
        char temp = board[r][c];
        board[r][c] = '#';
        bool res = dfs(r + 1, c, k + 1, board, word) ||
                   dfs(r - 1, c, k + 1, board, word) ||
                   dfs(r, c + 1, k + 1, board, word) ||
                   dfs(r, c - 1, k + 1, board, word);
        board[r][c] = temp;
        return res;
    }
public:
