class Solution {
    vector<string> res;
    int dx[4] = {1, 0, 0, -1};
    int dy[4] = {0, -1, 1, 0};
    char dChar[4] = {'D', 'L', 'R', 'U'};
    void dfs(int r, int c, int n, string path, vector<vector<int>>& m, vector<vector<int>>& vis) {
        if (r == n - 1 && c == n - 1) {
            res.push_back(path);
            return;
        }
        vis[r][c] = 1;
        for (int i = 0; i < 4; i++) {
            int nr = r + dx[i], nc = c + dy[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && !vis[nr][nc] && m[nr][nc] == 1) {
                dfs(nr, nc, n, path + dChar[i], m, vis);
            }
        }
        vis[r][c] = 0;
    }
public:
    vector<string> findPath(vector<vector<int>>& m, int n) {
        if (m[0][0] == 0 || m[n-1][n-1] == 0) return {};
        vector<vector<int>> vis(n, vector<int>(n, 0));
        dfs(0, 0, n, "", m, vis);
        return res;
    }
};

