        if (r == n - 1 && c == n - 1) {
            res.add(path);
            return;
        }
        vis[r][c] = 1;
        for (int i = 0; i < 4; i++) {
            int nr = r + dx[i], nc = c + dy[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && vis[nr][nc] == 0 && m[nr][nc] == 1) {
