function findPath(m, n) {
  const res = [];
  if (m[0][0] === 0 || m[n-1][n-1] === 0) return res;
  const dirs = [['D', 1, 0], ['L', 0, -1], ['R', 0, 1], ['U', -1, 0]];
  const vis = Array.from({ length: n }, () => new Array(n).fill(0));
  function dfs(r, c, path) {
    if (r === n - 1 && c === n - 1) {
      res.push(path);
      return;
    }
    vis[r][c] = 1;
    for (const [ch, dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n && !vis[nr][nc] && m[nr][nc] === 1) {
        dfs(nr, nc, path + ch);
      }
    }
    vis[r][c] = 0;
  }
  dfs(0, 0, '');
  return res;
}

