        }
    }
}

class WordDictionary {
    constructor() { this.root = {}; }
    addWord(word) {
        let curr = this.root;
        for (let c of word) {
            if (!curr[c]) curr[c] = {};
            curr = curr[c];
        }
        curr['#'] = true;
    }
    search(word) {
        const dfs = (node, idx) => {
            if (idx === word.length) return !!node['#'];
            const c = word[idx];
            if (c === '.') {
                for (let key in node) {
                    if (key !== '#' && dfs(node[key], idx + 1)) return true;
                }
                return false;
            } else {
                if (!node[c]) return false;
                return dfs(node[c], idx + 1);
            }
        };
        return dfs(this.root, 0);
    }
}

def longestCommonPrefix(strs: list[str]) -> str:
    if not strs: return ""
    # Alternative Trie traversal logic
    root = {}
    for word in strs:
        if not word: return ""
        curr = root
        for c in word:
            if c not in curr: curr[c] = {}
            curr = curr[c]
        curr['#'] = True

    prefix = []
    curr = root
    while len(curr) == 1 and '#' not in curr:
        char = list(curr.keys())[0]
        prefix.append(char)
        curr = curr[char]
    return ''.join(prefix)

