class BinaryTrieNode:
    def __init__(self):
        self.children = [None, None]

class BinaryTrie:
    def __init__(self):
        self.root = BinaryTrieNode()

    def insert(self, num: int):
        curr = self.root
        for i in range(30, -1, -1):
            bit = (num >> i) & 1
            if not curr.children[bit]:
                curr.children[bit] = BinaryTrieNode()
            curr = curr.children[bit]

    def get_max_xor(self, num: int) -> int:
        curr = self.root
        max_xor = 0
        for i in range(30, -1, -1):
            bit = (num >> i) & 1
            opp_bit = 1 - bit
            if curr.children[opp_bit]:
                max_xor |= (1 << i)
                curr = curr.children[opp_bit]
            else:
                curr = curr.children[bit]
        return max_xor

def findMaximumXOR(nums: list[int]) -> int:
    trie = BinaryTrie()
    for num in nums: trie.insert(num)
    return max(trie.get_max_xor(num) for num in nums)

