public class HashTableChaining {
    static class Node {
        String key; int val;
        Node(String k, int v) { key = k; val = v; }
    }
    private LinkedList<Node>[] table;
    private int capacity;

    public HashTableChaining(int cap) {
        capacity = cap;
        table = new LinkedList[cap];
        for (int i = 0; i < cap; i++) table[i] = new LinkedList<>();
    }

    public void put(String key, int val) {
        int idx = Math.abs(key.hashCode()) % capacity;
        for (Node node : table[idx]) {
            if (node.key.equals(key)) { node.val = val; return; }
        }
        table[idx].add(new Node(key, val));
    }
}

class HashTableChaining {
    constructor(capacity = 10) {
        this.capacity = capacity;
        this.table = new Array(capacity).fill(null).map(() => []);
    }
    _hash(key) {
        let hash = 0;
        for (let c of key) hash = (hash * 31 + c.charCodeAt(0)) % this.capacity;
        return hash;
    }
    put(key, value) {
        const idx = this._hash(key);
        const bucket = this.table[idx];
        for (let pair of bucket) {
            if (pair[0] === key) { pair[1] = value; return; }
        }
        bucket.push([key, value]);
    }
}

def isAnagram(s: str, t: str) -> bool:
    if len(s) != len(t): return False
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1
    for char in t:
        if char not in counts or counts[char] == 0:
            return False
        counts[char] -= 1
    return True

