    if (n <= 0) return arr;
    const buckets = Array.from({ length: n }, () => []);
    for (let num of arr) {
        let bi = Math.floor(n * num);
        if (bi === n) bi = n - 1;
        buckets[bi].push(num);
    }
    for (let i = 0; i < n; i++) buckets[i].sort((a, b) => a - b);
    return buckets.flat();
}

def shell_sort(arr: list[int]) -> list[int]:
    n = len(arr)
    gap = n // 2
    while gap > 0:
        for i in range(gap, n):
            temp = arr[i]
            j = i
            while j >= gap and arr[j - gap] > temp:
                arr[j] = arr[j - gap]
                j -= gap
            arr[j] = temp
        gap //= 2
    return arr

