    int pop() {
        int root = heap[0];
        heap[0] = heap.back(); heap.pop_back();
        if (!heap.empty()) siftDown(0);
        return root;
    }
};

import java.util.ArrayList;

public class MinHeap {
    private ArrayList<Integer> heap = new ArrayList<>();

    public void push(int val) {
        heap.add(val);
        siftUp(heap.size() - 1);
    }

    public int pop() {
        int root = heap.get(0);
        int last = heap.remove(heap.size() - 1);
        if (!heap.isEmpty()) {
            heap.set(0, last);
            siftDown(0);
        }
        return root;
    }

    private void siftUp(int i) {
        int parent = (i - 1) / 2;
        if (i > 0 && heap.get(i) < heap.get(parent)) {
            int temp = heap.get(i); heap.set(i, heap.get(parent)); heap.set(parent, temp);
            siftUp(parent);
        }
    }

    private void siftDown(int i) {
        int smallest = i, left = 2 * i + 1, right = 2 * i + 2;
        if (left < heap.size() && heap.get(left) < heap.get(smallest)) smallest = left;
        if (right < heap.size() && heap.get(right) < heap.get(smallest)) smallest = right;
        if (smallest != i) {
            int temp = heap.get(i); heap.set(i, heap.get(smallest)); heap.set(smallest, temp);
            siftDown(smallest);
        }
    }
}

class MinHeap {
    constructor() { this.heap = []; }
    push(val) {
        this.heap.push(val);
        this._siftUp(this.heap.length - 1);
    }
    pop() {
        if (!this.heap.length) return null;
        if (this.heap.length === 1) return this.heap.pop();
        const root = this.heap[0];
        this.heap[0] = this.heap.pop();
        this._siftDown(0);
        return root;
    }
    _siftUp(i) {
        let parent = Math.floor((i - 1) / 2);
        if (i > 0 && this.heap[i] < this.heap[parent]) {
            [this.heap[i], this.heap[parent]] = [this.heap[parent], this.heap[i]];
            this._siftUp(parent);
        }
    }
    _siftDown(i) {
        let smallest = i, left = 2 * i + 1, right = 2 * i + 2;
        if (left < this.heap.length && this.heap[left] < this.heap[smallest]) smallest = left;
        if (right < this.heap.length && this.heap[right] < this.heap[smallest]) smallest = right;
        if (smallest !== i) {
            [this.heap[i], this.heap[smallest]] = [this.heap[smallest], this.heap[i]];
            this._siftDown(smallest);
        }
    }
}

